function Field({label,value,set,type='text',required=false,placeholder='',wide=false}){
 const listId=useId();
 const key='pbj-autosuggest-v1:'+String(label||'').trim().toLowerCase();
 const sensitive=/\b(nip|email|password|kata sandi)\b|nomor surat/i.test(String(label||''));
 const enabled=type==='text'&&!sensitive;
 const [suggestions,setSuggestions]=useState(()=>{if(!enabled)return [];try{const data=JSON.parse(localStorage.getItem(key)||'[]');return Array.isArray(data)?data.filter(x=>typeof x==='string').slice(0,15):[]}catch{return []}});
 const remember=()=>{const text=String(value??'').trim();if(!enabled||text.length<2)return;try{const next=[text,...suggestions.filter(x=>x.toLowerCase()!==text.toLowerCase())].slice(0,15);localStorage.setItem(key,JSON.stringify(next));setSuggestions(next)}catch{}};
 return <label className={'field'+(wide?' wide':'')}>{label}<input type={type} value={value??''} onChange={e=>set(e.target.value)} onBlur={remember} required={required} placeholder={placeholder} list={enabled?listId:undefined} autoComplete="off"/>{enabled&&suggestions.length>0&&<datalist id={listId}>{suggestions.map((item,i)=><option key={i} value={item}/>)}</datalist>}</label>
}
function Area({label,value,set,wide=false}){return <label className={'field'+(wide?' wide':'')}>{label}<textarea rows="2" value={value??''} onChange={e=>set(e.target.value)}/></label>}
function Dropdown({label,value,set,options,placeholder='Pilih '+label}){const optionLabel=option=>String(option).replace(/_/g,' ').replace(/\b\w/g,c=>c.toUpperCase());return <label className="field">{label}<select value={value??''} onChange={e=>set(e.target.value)}><option value="">{placeholder}</option>{options.map(option=><option key={option} value={option}>{optionLabel(option)}</option>)}</select></label>}
