 async function optimizeStampPng(file){
  if(!file)return null;
  try{
   const bitmap=await createImageBitmap(file);
   const scale=Math.min(1,1400/Math.max(bitmap.width,bitmap.height));
   if(scale===1&&file.size<=4*1024*1024){bitmap.close?.();return file}
   const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));
   const ctx=canvas.getContext('2d');ctx.clearRect(0,0,canvas.width,canvas.height);ctx.drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close?.();
   const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));
   if(!blob)return file;
   return new File([blob],file.name.replace(/\\.[^.]+$/,'')+'-optimized.png',{type:'image/png',lastModified:Date.now()});
  }catch{return file}
 }
 async function uploadStampWithRetry(file,path){
  let lastError;
  for(let attempt=0;attempt<2;attempt++){
   try{
    const result=await db.storage.from('tanda-tangan').upload(path,file,{upsert:false,contentType:'image/png'});
    if(!result.error)return result;
    lastError=result.error;
   }catch(error){lastError=error}
   if(attempt===0)await new Promise(resolve=>setTimeout(resolve,900));
  }
  throw new Error('Unggah stempel gagal setelah 2 percobaan: '+(lastError?.message||'koneksi ke penyimpanan terputus. Periksa jaringan lalu coba lagi.'));
 }
 async function saveSettingOpd(e){e.preventDefault();B(true);Err('');try{let path=settingEditOpd?.kop_surat_path||null,stampPath=settingEditOpd?.stempel_path||null;if(settingOpdFile){const ext=(settingOpdFile.name.split('.').pop()||'png').replace(/[^a-z0-9]/gi,'').toLowerCase();const up=await db.storage.from('kop-surat').upload(session.user.id+'/master-opd-'+Date.now()+'.'+ext,settingOpdFile,{upsert:false,contentType:settingOpdFile.type||'image/png'});if(up.error)throw up.error;path=up.data.path}if(settingOpdStampFile){const stampFile=await optimizeStampPng(settingOpdStampFile);if(stampFile.size>5*1024*1024)throw new Error('Ukuran stempel masih lebih dari 5 MB setelah diperkecil. Gunakan PNG yang lebih kecil.');const target=session.user.id+'/master-opd-stempel-'+Date.now()+'.png';const up=await uploadStampWithRetry(stampFile,target);stampPath=up.data.path}const payload={nama_opd:settingOpdName.trim(),alamat:settingOpdAddress.trim()||null,kop_surat_path:path,stempel_path:stampPath};const out=settingEditOpd?await db.from('opd').update(payload).eq('id',settingEditOpd.id):await db.from('opd').insert(payload);if(out.error)throw out.error;N('Data OPD dan stempel berhasil disimpan.');SettingOpdName('');SettingOpdAddress('');SettingOpdFile(null);SettingOpdStampFile(null);SettingEditOpd(null);await loadSettings()}catch(e){Err('Gagal menyimpan OPD: '+e.message)}finally{B(false)}}
